// A Map cache keeps keys alive forever; a WeakMap lets them be collected.
const strongCache = new Map();
const weakCache = new WeakMap();

function expensive(obj) {
  return Object.keys(obj).length * 100;
}
function cached(cache, obj) {
  if (!cache.has(obj)) cache.set(obj, expensive(obj));
  return cache.get(obj);
}

let data = { a: 1, b: 2 };
console.log(cached(weakCache, data), cached(weakCache, data));
console.log(cached(strongCache, data), strongCache.size);
data = null;                   // weak entry can now be collected
console.log("strong cache still holds:", strongCache.size);
console.log("weak cache has no size property:", weakCache.size);

// closure holding big data
function makeReader() {
  const big = new Array(1000).fill("x");
  return () => big.length;     // big stays alive while reader exists
}
let reader = makeReader();
console.log(reader());
reader = null;                 // closure and big become collectable

topics.description:
Events like `input`, `scroll`, `resize` and `mousemove` can fire hundreds of times per second. These three techniques keep your app fast.

### Debounce
Wait until the user **stops** triggering the event for `delay` ms, then run **once**. Each call resets the timer.
- Use for: search-as-you-type, auto-save, window resize end.
```js
function debounce(fn, delay) {
  let timer;
  return function (...args) {
    clearTimeout(timer);
    timer = setTimeout(() => fn.apply(this, args), delay);
  };
}
```

### Throttle
Run **at most once** per interval, no matter how often it is triggered.
- Use for: scroll position, mousemove, drag, game input, analytics.
```js
function throttle(fn, limit) {
  let waiting = false;
  return function (...args) {
    if (waiting) return;
    fn.apply(this, args);
    waiting = true;
    setTimeout(() => (waiting = false), limit);
  };
}
```

### Debounce vs throttle
| | Debounce | Throttle |
|---|---|---|
| Runs | after activity stops | at a steady rate during activity |
| Calls for 100 events in 1 s (delay 200ms) | 1 | about 5 |

### Memoization
Cache the result of a **pure** function by its arguments:
```js
const memoize = (fn) => {
  const cache = new Map();
  return (...args) => {
    const key = JSON.stringify(args);
    if (!cache.has(key)) cache.set(key, fn(...args));
    return cache.get(key);
  };
};
```
Great for expensive computations and recursive algorithms. Do not memoize impure functions or functions with huge input sets without a cache limit.

examples.code:
const debounce = (fn, ms) => {
  let t;
  return (...a) => { clearTimeout(t); t = setTimeout(() => fn(...a), ms); };
};
const throttle = (fn, ms) => {
  let wait = false;
  return (...a) => { if (wait) return; fn(...a); wait = true; setTimeout(() => (wait = false), ms); };
};
const memoize = (fn) => {
  const cache = new Map();
  return (n) => (cache.has(n) ? cache.get(n) : (cache.set(n, fn(n)), cache.get(n)));
};

const search = debounce((q) => console.log("debounced search:", q), 30);
const scroll = throttle((y) => console.log("throttled scroll:", y), 30);
["j", "ja", "jav", "java"].forEach((q) => search(q));      // only "java" runs
[1, 2, 3].forEach((y) => scroll(y));                        // only 1 runs

let calls = 0;
const slowSquare = memoize((n) => { calls++; return n * n; });
console.log(slowSquare(9), slowSquare(9), slowSquare(9), "real calls:", calls);

