const counters = { raw: 0, deb: 0, thr: 0 };
const bump = (k) => { counters[k]++; document.getElementById(k).textContent = counters[k]; };
const debounce = (fn, ms) => { let t; return (...a) => { clearTimeout(t); t = setTimeout(() => fn(...a), ms); }; };
const throttle = (fn, ms) => { let w = false; return (...a) => { if (w) return; fn(...a); w = true; setTimeout(() => (w = false), ms); }; };

const onEvent = () => bump("raw");
const onDeb = debounce(() => bump("deb"), 400);
const onThr = throttle(() => bump("thr"), 400);
document.getElementById("field").addEventListener("input", () => { onEvent(); onDeb(); onThr(); });
document.getElementById("pad").addEventListener("mousemove", () => { onEvent(); onDeb(); onThr(); });

