class EventBus {
  #handlers = new Map();
  on(event, fn) {
    if (!this.#handlers.has(event)) this.#handlers.set(event, new Set());
    this.#handlers.get(event).add(fn);
    return () => this.#handlers.get(event).delete(fn);   // unsubscribe
  }
  emit(event, data) {
    this.#handlers.get(event)?.forEach((fn) => fn(data));
  }
}
const bus = new EventBus();
const off = bus.on("login", (user) => console.log("welcome", user));
bus.on("login", (user) => console.log("analytics:", user));
bus.emit("login", "Asha");
off();
bus.emit("login", "Ravi");

const createShape = (type, size) => {
  const shapes = {
    square: () => ({ type, area: size * size }),
    circle: () => ({ type, area: +(Math.PI * size * size).toFixed(2) }),
  };
  return (shapes[type] ?? (() => { throw new Error("Unknown shape"); }))();
};
console.log(createShape("square", 3), createShape("circle", 2));

const N = 20000;
const items = Array.from({ length: N }, (_, i) => i);
const lookups = Array.from({ length: 2000 }, (_, i) => i * 10);

console.time("array.includes");
let found1 = 0;
for (const x of lookups) if (items.includes(x)) found1++;
console.timeEnd("array.includes");

const set = new Set(items);
console.time("set.has");
let found2 = 0;
for (const x of lookups) if (set.has(x)) found2++;
console.timeEnd("set.has");

console.log(found1 === found2, found1);
const t0 = performance.now();
let sum = 0;
for (let i = 0; i < 1e6; i++) sum += i;
console.log("loop result", sum, "took >= 0ms:", performance.now() - t0 >= 0);

const escapeHTML = (str) =>
  str.replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));

const evil = `<img src=x onerror="alert('hacked')">`;
console.log("raw  :", evil);
console.log("safe :", escapeHTML(evil));

const unsafeUrl = "javascript:alert(1)";
const isSafeUrl = (u) => {
  try { return ["http:", "https:"].includes(new URL(u, "https://example.com").protocol); }
  catch { return false; }
};
console.log(isSafeUrl(unsafeUrl), isSafeUrl("https://example.com/a"), isSafeUrl("/relative"));
